css:
.ex-hero h2, .ex-hero p {
  margin: 0;
}

.ex-hero a {
  color: inherit;
}

.ex-hero {
  --ex-hero-accent: #6d5dfc;
  --ex-hero-space: 48px;
  --ex-hero-align: left;
  padding: var(--ex-hero-space) 64px;
  background: radial-gradient(ellipse at 100% 0%, #d8f7ed, transparent 60%), radial-gradient(ellipse at 0% 100%, #ded5ff, transparent 65%), #faf9ff;
  color: #18233d;
  text-align: var(--ex-hero-align);
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-hero__badge {
  display: inline-block;
  padding: 6px 12px;
  border: 1px solid #d8d2ee;
  border-radius: 999px;
  font-size: 12px;
}

.ex-hero h2 {
  margin: 24px 0 16px;
  font-size: 64px;
  line-height: 1.08;
}

.ex-hero p {
  color: #57627b;
}

.ex-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
  justify-content: var(--ex-hero-align);
}

.ex-hero__actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 12px 18px;
  border-radius: 10px;
  text-decoration: none;
  font-weight: 600;
}

.ex-hero .ex-hero__primary {
  background: var(--ex-hero-accent);
  color: white;
}

.ex-hero__secondary {
  border: 1px solid #d8d2ee;
  background: rgba(255, 255, 255, 0.5);
}

@media (max-width: 480px) {
  .ex-hero {
    padding: var(--ex-hero-space) 24px;
  }

  .ex-hero h2 {
    font-size: 36px;
  }
}

.ex-hero, .ex-hero * {
  box-sizing: border-box;
}

.ex-hero a:focus-visible {
  outline: 3px solid var(--ex-hero-accent);
  outline-offset: 4px;
}

.ex-feature h2, .ex-feature p {
  margin: 0;
}

.ex-feature a {
  color: inherit;
}

.ex-feature {
  --ex-feature-accent: #267c6b;
  --ex-feature-gap: 32px;
  --ex-feature-radius: 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: var(--ex-feature-gap);
  padding: 36px;
  background: #f5f8f5;
  color: #183d36;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-feature__eyebrow {
  color: var(--ex-feature-accent);
  font-size: 12px;
  font-weight: 700;
}

.ex-feature h2 {
  margin: 16px 0;
  font-size: 44px;
  line-height: 1.12;
}

.ex-feature p {
  color: #576f65;
}

.ex-feature__text a {
  display: inline-flex;
  gap: 12px;
  margin-top: 24px;
  color: var(--ex-feature-accent);
  font-weight: 700;
}

.ex-feature__art {
  overflow: hidden;
  border-radius: var(--ex-feature-radius);
  background: #d7e8df;
}

.ex-feature__art svg {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

@media (max-width: 540px) {
  .ex-feature {
    grid-template-columns: 1fr;
    padding: 24px;
  }
}

.ex-feature, .ex-feature * {
  box-sizing: border-box;
}

.ex-feature a:focus-visible {
  outline: 3px solid var(--ex-feature-accent);
  outline-offset: 4px;
}

.ex-bento h2, .ex-bento h3, .ex-bento p {
  margin: 0;
}

.ex-bento {
  --ex-bento-accent: #6d5dfc;
  --ex-bento-gap: 12px;
  --ex-bento-radius: 20px;
  padding: 32px;
  background: #faf9f6;
  color: #202838;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-bento header > span {
  font-size: 12px;
  color: #687083;
}

.ex-bento h2 {
  margin: 8px 0 24px;
  font-size: 38px;
}

.ex-bento__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--ex-bento-gap);
}

.ex-bento__card {
  position: relative;
  overflow: hidden;
  padding: 24px;
  border-radius: var(--ex-bento-radius);
  background: #eeeaf9;
}

.ex-bento__main {
  grid-row: span 2;
  min-height: 260px;
  background: var(--ex-bento-accent);
  color: white;
}

.ex-bento__mint {
  background: #dff1e7;
}

.ex-bento__peach {
  background: #ffe9d9;
}

.ex-bento__wide {
  grid-column: span 2;
}

.ex-bento__number {
  display: block;
  opacity: .7;
  font-size: 12px;
  margin-bottom: 18px;
}

.ex-bento h3 {
  font-size: 19px;
  line-height: 1.2;
  margin-bottom: 10px;
}

.ex-bento__card p {
  font-size: 13px;
}

.ex-bento__orbits {
  position: relative;
  height: 100px;
  margin-top: 20px;
}

.ex-bento__orbits i {
  position: absolute;
  width: 100px;
  height: 100px;
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 50%;
}

.ex-bento__orbits i:nth-child(2) {
  left: 35px;
}

.ex-bento__orbits i:nth-child(3) {
  left: 70px;
}

@media (max-width: 540px) {
  .ex-bento {
    padding: 24px;
  }

  .ex-bento__grid {
    grid-template-columns: 1fr 1fr;
  }

  .ex-bento__main {
    grid-column: span 2;
    grid-row: auto;
    min-height: 0;
  }

  .ex-bento__orbits {
    display: none;
  }
}

@media (max-width: 340px) {
  .ex-bento__grid {
    grid-template-columns: 1fr;
  }

  .ex-bento__main, .ex-bento__wide {
    grid-column: auto;
  }
}

.ex-bento, .ex-bento * {
  box-sizing: border-box;
}

.ex-bento a:focus-visible {
  outline: 3px solid var(--ex-bento-accent);
  outline-offset: 4px;
}

.ex-cards h2, .ex-cards h3, .ex-cards p {
  margin: 0;
}

.ex-cards a {
  color: inherit;
}

.ex-cards {
  --ex-cards-accent: #9e90ff;
  --ex-cards-lift: 6px;
  --ex-cards-duration: 200ms;
  padding: 36px;
  background: #141a2a;
  color: #f6f7fc;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-cards header > span {
  font-size: 12px;
  color: #aeb8d0;
}

.ex-cards h2 {
  margin: 10px 0 24px;
  font-size: 38px;
}

.ex-cards__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
}

.ex-cards__card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 24px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 16px;
  background: #20273b;
  text-decoration: none;
  transition: transform var(--ex-cards-duration), box-shadow var(--ex-cards-duration), border-color var(--ex-cards-duration);
}

.ex-cards__icon {
  color: var(--ex-cards-accent);
  font-size: 34px;
  margin-bottom: 24px;
}

.ex-cards h3 {
  margin-bottom: 10px;
  font-size: 20px;
}

.ex-cards__card p {
  color: #bdc7dc;
  font-size: 13px;
}

.ex-cards__arrow {
  color: var(--ex-cards-accent);
  font-size: 22px;
  padding-top: 24px;
  margin-top: auto;
}

.ex-cards__card:hover, .ex-cards__card:focus-visible {
  transform: translateY(calc(-1 * var(--ex-cards-lift)));
  border-color: var(--ex-cards-accent);
  box-shadow: 0 14px 28px rgba(0, 0, 0, 0.27);
}

@media (max-width: 540px) {
  .ex-cards {
    padding: 24px;
  }

  .ex-cards__grid {
    grid-template-columns: 1fr;
  }

  .ex-cards__icon {
    margin-bottom: 12px;
  }
}

.ex-cards, .ex-cards * {
  box-sizing: border-box;
}

.ex-cards a:focus-visible {
  outline: 3px solid var(--ex-cards-accent);
  outline-offset: 4px;
}

.ex-gallery h2, .ex-gallery h3, .ex-gallery p {
  margin: 0;
}

.ex-gallery a {
  color: inherit;
}

.ex-gallery {
  --ex-gallery-accent: #a05f38;
  --ex-gallery-gap: 18px;
  --ex-gallery-card-width: 240px;
  padding: 32px;
  background: #faf5ee;
  color: #352b25;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-gallery h2 {
  font-size: 38px;
}

.ex-gallery header p {
  margin-top: 12px;
  font-size: 13px;
  color: #79685b;
}

.ex-gallery__track {
  display: flex;
  gap: var(--ex-gallery-gap);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding: 24px 4px 16px;
}

.ex-gallery__track:focus-visible {
  outline: 3px solid var(--ex-gallery-accent);
  outline-offset: 3px;
}

.ex-gallery__card {
  flex: 0 0 min(var(--ex-gallery-card-width), 85%);
  scroll-snap-align: start;
  text-decoration: none;
}

.ex-gallery__art {
  overflow: hidden;
  border-radius: 16px;
  background: #e9f2f2;
}

.ex-gallery__art svg {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

.ex-gallery__card > span {
  display: block;
  margin: 16px 0 6px;
  font-size: 11px;
  color: var(--ex-gallery-accent);
}

.ex-gallery h3 {
  font-size: 20px;
}

.ex-gallery__card p {
  margin-top: 8px;
  font-size: 13px;
  color: #79685b;
}

@media (max-width: 480px) {
  .ex-gallery {
    padding: 24px;
  }
}

.ex-gallery, .ex-gallery * {
  box-sizing: border-box;
}

.ex-gallery a:focus-visible {
  outline: 3px solid var(--ex-gallery-accent);
  outline-offset: 4px;
}

.ex-pricing h2, .ex-pricing h3, .ex-pricing p {
  margin: 0;
}

.ex-pricing a {
  color: inherit;
}

.ex-pricing {
  --ex-pricing-accent: #5265da;
  --ex-pricing-gap: 14px;
  --ex-pricing-radius: 18px;
  padding: 36px;
  background: #f6f7fc;
  color: #202838;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-pricing header {
  text-align: center;
}

.ex-pricing h2 {
  font-size: 38px;
}

.ex-pricing header p {
  margin-top: 10px;
  color: #687083;
}

.ex-pricing__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--ex-pricing-gap);
  margin-top: 32px;
}

.ex-pricing__card {
  position: relative;
  display: flex;
  flex-direction: column;
  padding: 24px;
  border: 1px solid #dce0ef;
  border-radius: var(--ex-pricing-radius);
  background: white;
}

.ex-pricing__featured {
  border: 2px solid var(--ex-pricing-accent);
  box-shadow: 0 12px 30px rgba(32, 40, 56, 0.06);
}

.ex-pricing__badge {
  align-self: flex-start;
  margin-bottom: 14px;
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--ex-pricing-accent);
  color: white;
  font-size: 11px;
}

.ex-pricing h3 {
  font-size: 19px;
}

.ex-pricing__price {
  margin-top: 16px;
  font-size: 30px;
  font-weight: 700;
}

.ex-pricing__price span {
  font-size: 12px;
  font-weight: 400;
  color: #687083;
}

.ex-pricing ul {
  padding: 0;
  margin: 24px 0;
  list-style: none;
  font-size: 13px;
}

.ex-pricing li {
  margin-bottom: 10px;
}

.ex-pricing li::before {
  content: '✓';
  color: var(--ex-pricing-accent);
  margin-right: 8px;
}

.ex-pricing__card a {
  display: block;
  text-align: center;
  padding: 10px 12px;
  border: 1px solid #dce0ef;
  border-radius: 9px;
  margin-top: auto;
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
}

.ex-pricing .ex-pricing__featured a {
  background: var(--ex-pricing-accent);
  color: white;
  border-color: var(--ex-pricing-accent);
}

@media (max-width: 580px) {
  .ex-pricing {
    padding: 24px;
  }

  .ex-pricing__grid {
    grid-template-columns: 1fr;
  }
}

.ex-pricing, .ex-pricing * {
  box-sizing: border-box;
}

.ex-pricing a:focus-visible {
  outline: 3px solid var(--ex-pricing-accent);
  outline-offset: 4px;
}

.ex-faq h2, .ex-faq p {
  margin: 0;
}

.ex-faq {
  --ex-faq-accent: #387b68;
  --ex-faq-space: 18px;
  --ex-faq-radius: 12px;
  padding: 36px;
  background: #fafbf8;
  color: #253c34;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-faq header > span {
  font-size: 12px;
  color: var(--ex-faq-accent);
  font-weight: 600;
}

.ex-faq h2 {
  margin: 10px 0;
  font-size: 38px;
}

.ex-faq header p {
  color: #677b73;
}

.ex-faq__list {
  margin-top: 28px;
}

.ex-faq details {
  margin-bottom: 10px;
  border: 1px solid #dce5de;
  border-radius: var(--ex-faq-radius);
  background: white;
}

.ex-faq summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: var(--ex-faq-space);
  list-style: none;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
}

.ex-faq summary::-webkit-details-marker {
  display: none;
}

.ex-faq summary > span::before {
  content: '+';
  font-size: 23px;
  font-weight: 400;
  color: var(--ex-faq-accent);
}

.ex-faq details[open] summary > span::before {
  content: '−';
}

.ex-faq details[open] {
  border-color: var(--ex-faq-accent);
}

.ex-faq details p {
  padding: 0 var(--ex-faq-space) var(--ex-faq-space);
  font-size: 13px;
  color: #677b73;
}

@media (max-width: 480px) {
  .ex-faq {
    padding: 24px;
  }
}

.ex-faq, .ex-faq * {
  box-sizing: border-box;
}

.ex-faq a:focus-visible, .ex-faq summary:focus-visible {
  outline: 3px solid var(--ex-faq-accent);
  outline-offset: 4px;
}

.ex-glass h2, .ex-glass p {
  margin: 0;
}

.ex-glass a {
  color: inherit;
}

.ex-glass {
  --ex-glass-accent: #9873ff;
  --ex-glass-opacity: 18%;
  --ex-glass-blur: 12px;
  position: relative;
  overflow: hidden;
  padding: 48px 32px;
  background: linear-gradient(135deg, #132c49, #282344);
  color: white;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-glass::before, .ex-glass::after {
  content: '';
  position: absolute;
  z-index: 0;
  width: 260px;
  height: 260px;
  border-radius: 50%;
}

.ex-glass::before {
  top: -70px;
  right: -40px;
  background: var(--ex-glass-accent);
}

.ex-glass::after {
  bottom: -100px;
  left: -60px;
  background: #5bd5c1;
}

.ex-glass__panel {
  position: relative;
  z-index: 1;
  max-width: 680px;
  margin: auto;
  padding: 32px;
  border: 1px solid rgba(255, 255, 255, 0.33);
  border-radius: 24px;
  background: rgb(255 255 255 / var(--ex-glass-opacity));
  -webkit-backdrop-filter: blur(var(--ex-glass-blur));
  backdrop-filter: blur(var(--ex-glass-blur));
}

.ex-glass__panel > span {
  font-size: 12px;
  color: #e5e9f5;
}

.ex-glass h2 {
  margin: 16px 0;
  font-size: 44px;
  line-height: 1.12;
}

.ex-glass p {
  max-width: 45ch;
  color: #edf0fa;
}

.ex-glass__panel a {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
  text-align: center;
  gap: 16px;
  padding: 12px 18px;
  border-radius: 10px;
  background: white;
  color: #111111;
  text-decoration: none;
  font-weight: 600;
  font-size: 14px;
  margin-top: 24px;
  transition: transform 180ms ease, box-shadow 180ms ease, background-color 180ms ease;
}

@media (max-width: 480px) {
  .ex-glass {
    padding: 32px 20px;
  }

  .ex-glass__panel {
    padding: 24px;
  }
}

.ex-glass, .ex-glass * {
  box-sizing: border-box;
}

.ex-glass a:focus-visible {
  outline: 3px solid var(--ex-glass-accent);
  outline-offset: 4px;
}

.ex-glass__panel a:hover, .ex-glass__panel a:focus-visible {
  background-color: #eee8ff;
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(19, 44, 73, 0.25);
}

.ex-navbar h2, .ex-navbar p {
  margin: 0;
}

.ex-navbar a {
  color: inherit;
}

.ex-navbar {
  --ex-navbar-accent: #6453c7;
  --ex-navbar-opacity: 28%;
  --ex-navbar-blur: 12px;
  min-height: 760px;
  padding: 110px 32px 40px;
  background: radial-gradient(circle at 10% 20%, #dfc8fb, transparent 45%), radial-gradient(circle at 90% 50%, #b7e5dc, transparent 55%), #f6f5fb;
  color: #24243d;
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  width: 100%;
  max-width: 100%;
}

.ex-navbar__bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 24px;
  background: rgb(255 255 255 / var(--ex-navbar-opacity));
  -webkit-backdrop-filter: blur(var(--ex-navbar-blur)) saturate(150%);
  backdrop-filter: blur(var(--ex-navbar-blur)) saturate(150%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.6);
}

.ex-navbar__logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 23px;
  font-weight: 700;
  text-decoration: none;
}

.ex-navbar__logo span {
  color: var(--ex-navbar-accent);
}

.ex-navbar__space {
  flex: 1;
}

.ex-navbar__links {
  display: flex;
  align-items: center;
  gap: 20px;
}

.ex-navbar__links a {
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
}

.ex-navbar__links a:hover, .ex-navbar__links a:focus-visible {
  color: var(--ex-navbar-accent);
  text-decoration: underline;
}

.ex-navbar__toggle, .ex-navbar__hamburger {
  display: none;
}

.ex-navbar__intro > span {
  color: var(--ex-navbar-accent);
  font-size: 12px;
  font-weight: 600;
}

.ex-navbar h2 {
  margin: 18px 0;
  font-size: 54px;
  line-height: 1.1;
}

.ex-navbar__intro p {
  max-width: 48ch;
  color: #667083;
}

.ex-navbar__demo {
  margin-top: 70px;
  scroll-margin-top: 90px;
}

.ex-navbar__demo > span {
  font-size: 12px;
  font-weight: 700;
}

.ex-navbar__demo > div {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 16px;
}

.ex-navbar__demo article {
  flex: 1 1 100px;
  padding: 40px 20px;
  border: 1px solid rgba(255, 255, 255, 0.67);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.53);
  font-size: 16px;
  font-weight: 600;
}

.ex-navbar__contact {
  margin-top: 100px;
  padding-top: 24px;
  border-top: 1px solid rgba(100, 83, 199, 0.2);
  scroll-margin-top: 90px;
  font-size: 13px;
}

@media (max-width: 540px) {
  .ex-navbar {
    padding: 100px 24px 40px;
  }

  .ex-navbar__bar {
    padding: 12px 20px;
    gap: 8px;
  }

  .ex-navbar__logo {
    font-size: 20px;
  }

  .ex-navbar__toggle {
    display: block;
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
    overflow: hidden;
  }

  .ex-navbar__hamburger {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 5px;
    width: 40px;
    height: 40px;
    padding: 10px;
    border: 1px solid #d8d3e7;
    border-radius: 10px;
    cursor: pointer;
  }

  .ex-navbar__hamburger span {
    display: block;
    height: 2px;
    width: 18px;
    background: var(--ex-navbar-accent);
    transition: transform 200ms ease, opacity 200ms ease;
  }

