  margin: 0;
}

.ex-state-theme a {
  color: inherit;
}

.ex-state-theme {
  --ex-state-theme-accent: #6453c7;
  --ex-state-theme-light: #fbfdff;
  --ex-state-theme-dark: #15233b;
  background: var(--ex-state-theme-light);
  transition: background-color 200ms ease, color 200ms ease;
  width: 100%;
  font-family: system-ui, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  color: #17263c;
}

.ex-state-theme header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 20px 24px;
  border-bottom: 1px solid #d9e0eb;
}

.ex-state-theme label {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  font-size: 14px;
}

.ex-state-theme .interruptor {
  position: relative;
  width: 46px;
  height: 28px;
  border-radius: 16px;
  background: #cbd5e1;
}

.ex-state-theme .interruptor::after {
  content: '';
  position: absolute;
  left: 3px;
  top: 3px;
  width: 22px;
  height: 22px;
  background: white;
  border-radius: 50%;
  transition: transform 200ms ease;
}

.ex-state-theme .contingut {
  padding: 28px 24px;
}

.ex-state-theme h2 {
  font-size: 30px;
  line-height: 1.2;
  margin: 18px 0 24px;
}

.ex-state-theme article {
  padding: 24px;
  border: 1px solid #d9e0eb;
  border-radius: 16px;
  background: #f0f4ff;
}

.ex-state-theme article p {
  margin: 12px 0 18px;
}

.ex-state-theme article a {
  font-weight: 700;
  color: var(--ex-state-theme-accent);
}

.ex-state-theme .mode-fosc {
  display: none;
}

.ex-state-theme:has(#theme-dark:checked) {
  background: var(--ex-state-theme-dark);
  color: #edf2f7;
}

.ex-state-theme:has(#theme-dark:checked) header {
  border-color: #3c4c65;
}

.ex-state-theme:has(#theme-dark:checked) article {
  background: #23344f;
  border-color: #3c4c65;
}

.ex-state-theme:has(#theme-dark:checked) article a {
  color: #d9ceff;
}

.ex-state-theme:has(#theme-dark:checked) .interruptor {
  background: var(--ex-state-theme-accent);
}

.ex-state-theme:has(#theme-dark:checked) .interruptor::after {
  transform: translateX(18px);
}

.ex-state-theme:has(#theme-dark:checked) .mode-clar {
  display: none;
}

.ex-state-theme:has(#theme-dark:checked) .mode-fosc {
  display: block;
}

.ex-state-theme, .ex-state-theme * {
  box-sizing: border-box;
}

.ex-state-theme .estat {
  display: none;
}
